INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist After-Sales nur für physische Produkte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dienstleistungen wichtig"}, {"text": "Ja", "correct": false, "because": "Nicht auf Produkte beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit After-Sales?', 3, '[{"text": "Kundenzufriedenheit erhöhen", "correct": true, "because": "Fördert Loyalität"}, {"text": "Produktentwicklung", "correct": false, "because": "Nicht primär"}, {"text": "Kosten senken", "correct": false, "because": "Fokus auf Service"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen gehören zum After-Sales?', 5, '[{"text": "Kundensupport", "correct": true, "because": "Hilft bei Problemen"}, {"text": "Garantieleistungen", "correct": true, "because": "Sichert Qualität"}, {"text": "Marketingkampagnen", "correct": false, "because": "Vor Verkauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) After-Sales fördert Kundenbindung. b) Es ist nur für teure Produkte nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Preisklassen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung von After-Sales?', 4, '[{"text": "Kundenbedürfnisse", "correct": false, "because": "Kern des Services"}, {"text": "Supportkanäle", "correct": false, "because": "Wichtig für Erreichbarkeit"}, {"text": "Produktfarbe", "correct": true, "because": "Irrelevant für Service"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob After-Sales auch Ersatzteile umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Teil des Supports"}, {"text": "Nein", "correct": false, "because": "Häufig enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für guten After-Sales?', 3, '[{"text": "Schnelle Reaktionszeit", "correct": true, "because": "Erhöht Zufriedenheit"}, {"text": "Hohe Preise", "correct": false, "because": "Abschreckend"}, {"text": "Wenig Kontakt", "correct": false, "because": "Kunden brauchen Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einem starken After-Sales-Angebot?', 5, '[{"text": "Reparaturservice", "correct": true, "because": "Löst Probleme"}, {"text": "Rückgaberecht", "correct": true, "because": "Sichert Vertrauen"}, {"text": "Produktwerbung", "correct": false, "because": "Vorverkauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) After-Sales steigert Loyalität. b) Es ist immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten können anfallen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei After-Sales unwichtig?', 4, '[{"text": "Kundenservicequalität", "correct": false, "because": "Entscheidend für Erfolg"}, {"text": "Reaktionszeit", "correct": false, "because": "Beeinflusst Zufriedenheit"}, {"text": "Verpackungsdesign", "correct": true, "because": "Nicht After-Sales-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist After-Sales Teil des Verkaufsprozesses?', 2, '[{"text": "Nein", "correct": true, "because": "Folgt dem Verkauf"}, {"text": "Ja", "correct": false, "because": "Nachgelagerte Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt guter After-Sales?', 4, '[{"text": "Wiederholungskäufe", "correct": true, "because": "Zufriedene Kunden kommen zurück"}, {"text": "Positive Mundpropaganda", "correct": true, "because": "Empfehlungen steigen"}, {"text": "Geringere Produktionskosten", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass After-Sales nur bei Problemen wichtig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch präventiv wertvoll"}, {"text": "Ja", "correct": false, "because": "Proaktiver Service zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im After-Sales?', 3, '[{"text": "Kundenorientierung", "correct": true, "because": "Zufriedenheit ist Ziel"}, {"text": "Kostensenkung", "correct": false, "because": "Servicequalität wichtiger"}, {"text": "Schnellverkauf", "correct": false, "because": "Nach Verkauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) After-Sales kann Umsatz steigern. b) Es ersetzt den Verkauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat schlechter After-Sales?', 5, '[{"text": "Kundenverlust", "correct": true, "because": "Unzufriedenheit schadet"}, {"text": "Negative Bewertungen", "correct": true, "because": "Ruf leidet"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei After-Sales unwichtig?', 3, '[{"text": "Supportverfügbarkeit", "correct": false, "because": "Kern des Services"}, {"text": "Garantiebedingungen", "correct": false, "because": "Wichtig für Vertrauen"}, {"text": "Produktpreis", "correct": true, "because": "Nach Verkauf festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann After-Sales langfristige Beziehungen fördern?', 3, '[{"text": "Ja", "correct": true, "because": "Vertrauen stärkt Bindung"}, {"text": "Nein", "correct": false, "because": "Langfristiger Effekt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob After-Sales auch Schulungen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Teil des Supports"}, {"text": "Nein", "correct": false, "because": "Kann enthalten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Service wähle ich für effektiven After-Sales?', 4, '[{"text": "24/7-Support", "correct": true, "because": "Maximale Erreichbarkeit"}, {"text": "Einmalige Antwort", "correct": false, "because": "Zu begrenzt"}, {"text": "Kein Kontakt", "correct": false, "because": "Schadet Zufriedenheit"}]');
